"best":53904,"status":"classified","laps":[{"n":1,"ms":53904,"elapsed":94453}]},{"slug":"pablo-fonseca","position":23,"kart":123,"best":53930,"status":"classified","laps":[{"n":1,"ms":53930,"elapsed":68991}]},{"slug":"fernando-godoy","position":24,"kart":145,"best":54013,"status":"classified","laps":[{"n":1,"ms":54013,"elapsed":71046}]},{"slug":"gabriel-fernandes","position":25,"kart":130,"best":54026,"status":"classified","laps":[{"n":1,"ms":54026,"elapsed":71952}]},{"slug":"guilherme-faria","position":26,"kart":131,"best":54135,"status":"classified","laps":[{"n":1,"ms":54135,"elapsed":77933}]},{"slug":"newton","position":27,"kart":108,"best":54323,"status":"classified","laps":[{"n":1,"ms":54323,"elapsed":71002}]},{"slug":"rafael-morais","position":28,"kart":151,"best":54397,"status":"classified","laps":[{"n":1,"ms":54397,"elapsed":69999}]},{"slug":"wesley-cardoso","position":29,"kart":116,"best":54754,"status":"classified","laps":[{"n":1,"ms":54754,"elapsed":70472}]},{"slug":"raphael-werner","position":30,"kart":127,"best":54960,"status":"classified","laps":[{"n":1,"ms":54960,"elapsed":70235}]},{"slug":"rafael-teodoro","position":31,"kart":133,"best":55229,"status":"classified","laps":[{"n":1,"ms":55229,"elapsed":69719}]},{"slug":"lucas-gabriel-voieta-parreira","position":32,"kart":117,"best":55267,"status":"classified","laps":[{"n":1,"ms":55267,"elapsed":79872}]},{"slug":"lucca-dambros","position":33,"kart":146,"best":55521,"status":"classified","laps":[{"n":1,"ms":55521,"elapsed":70191}]}]}]$payload$::jsonb;
  item jsonb;
  entry jsonb;
  target_stage uuid;
  target_session uuid;
  target_result uuid;
  target_driver uuid;
  target_entry uuid;
  inserted integer;
begin
  for item in select * from jsonb_array_elements(payload) loop
    select id into target_stage from public.stages
    where deleted_at is null and (starts_at at time zone 'America/Sao_Paulo')::date = (item->>'stage_date')::date;
    if target_stage is null then continue; end if; -- replay de CI sem o calendário de produção

    select id into target_session from public.sessions
    where stage_id = target_stage and name = item->>'name' and deleted_at is null;
    if target_session is null then
      insert into public.sessions(stage_id, name, kind, starts_at, status)
      values (target_stage, item->>'name', 'qualifying', (item->>'starts_at')::timestamptz, 'homologated')
      returning id into target_session;
    end if;

    select id into target_result from public.results
    where session_id = target_session and deleted_at is null and category_id is null;
    if target_result is null then
      insert into public.results(stage_id, session_id, category_id, title, status, version, fastest_lap_ms, published_at,
        source_system, external_racing_id, external_imported_at)
      values (target_stage, target_session, null,
        format('Tomada de tempo - %sa etapa - Corrida %s', (select count(*) from public.stages s2
          where s2.deleted_at is null and s2.season_id = (select season_id from public.stages where id = target_stage)
            and s2.starts_at <= (select starts_at from public.stages where id = target_stage)), item->>'race'),
        'published', 1,
        (select min((e->>'best')::integer) from jsonb_array_elements(item->'entries') e where e->>'best' is not null),
        now(), 'kartodromo_timing', (item->>'external_racing_id')::bigint, now())
      returning id into target_result;
    end if;

    for entry in select * from jsonb_array_elements(item->'entries') loop
      select d.id into target_driver from public.drivers d
      where d.slug = entry->>'slug' and d.deleted_at is null;
      if target_driver is null then raise exception 'Piloto % não encontrado', entry->>'slug'; end if;

      insert into public.result_entries(result_id, driver_id, position, kart_number, laps, best_lap_ms, status, pole, fastest_lap, penalty_points)
      values (target_result, target_driver, (entry->>'position')::integer, nullif(entry->>'kart', '')::integer,
        jsonb_array_length(entry->'laps'), nullif(entry->>'best', '')::integer, entry->>'status', false, false, 0)
      on conflict (result_id, driver_id) where deleted_at is null do update set
        position = excluded.position, kart_number = excluded.kart_number, laps = excluded.laps,
        best_lap_ms = excluded.best_lap_ms, status = excluded.status
      returning id into target_entry;

      insert into public.laps(result_id, result_entry_id, driver_id, lap_number, lap_time_ms, elapsed_time_ms, valid)
      select target_result, target_entry, target_driver, (lap->>'n')::integer, (lap->>'ms')::integer,
             nullif(lap->>'elapsed', '')::bigint, true
      from jsonb_array_elements(entry->'laps') lap
      on conflict (result_entry_id, lap_number) where deleted_at is null do update set
        lap_time_ms = excluded.lap_time_ms, elapsed_time_ms = excluded.elapsed_time_ms;
    end loop;

    -- tomada de tempo não vale ponto (o gatilho calcula pela posição; aqui fica zerado)
    update public.result_entries set points = 0 where result_id = target_result;
  end loop;

  select count(*) into inserted from public.laps l join public.results r on r.id = l.result_id
  join public.sessions s on s.id = r.session_id where s.kind = 'qualifying' and l.deleted_at is null;
  if inserted < 187 and exists (select 1 from public.stages where (starts_at at time zone 'America/Sao_Paulo')::date = '2026-11-10') then
    raise exception 'Tomadas de tempo: esperadas 187 voltas, gravadas %', inserted;
  end if;
end
$quali$;
